insert into public.rules (id, slug, title, category, rule_type, short_explanation, tts_text, mnemonic, source, visibility, is_active)
values
  ('e5062a50-cc60-50c4-9c43-1e648ffd10f6', 'ck-after-short-vowel', 'Short vowel + ck: back, pick, luck', 'english_spelling', 'language_rule', 'At the end of a short word, write ck for the /k/ sound after a short vowel: back, pick, luck, clock, truck. After a long vowel, two vowels or a consonant, write just k: make, book, bank.', 'After a short vowel, the k sound is written ck.', 'Short vowel, strong end: ck. Long vowel or consonant: just k.', 'built-in', 'public', true),
  ('0573243f-2f5c-57ac-a75f-edb60fe6715d', 'ph-and-gh-f-sound', 'The f sound as ph or gh: phone, laugh', 'english_spelling', 'language_rule', 'The /f/ sound is not always written f. In many words from Greek it is ph: phone, photo, alphabet, physics, phrase. In a few common words it is gh: laugh, enough, tough, rough, cough.', 'The f sound can be written ph or gh.', 'Phone and photo: ph. Laugh, enough, tough: gh.', 'built-in', 'public', true),
  ('7ed6bbf4-18f1-515a-bc2d-468d28349601', 'double-letters-in-common-words', 'Double cc, mm, ss, rr: address, success, arrive', 'double_consonants', 'language_rule', 'Many common words have double consonants that must be remembered: address, success, message, necessary, committee, arrived and tomorrow. Write the whole word carefully; one missing letter changes the spelling.', 'Some common words need double consonants.', 'Address, success, message: double letters travel together.', 'built-in', 'public', true),
  ('7a4cc6f9-b01b-5058-97dc-1de6ea99a383', 'all-words-single-l', 'all- compounds → one l: always, already, almost', 'double_consonants', 'language_rule', 'When all is part of a longer word, it usually keeps only one l: always, already, almost, also, although and altogether. The word all by itself has two l letters.', 'In words with all, usually write only one l.', 'All alone has two l letters; inside a word, drop one.', 'built-in', 'public', true),
  ('e00c9954-3003-5bdb-bb3f-2b2e54af1c5b', 'silent-l', 'Silent l: could, walk, half, calm', 'silent_letters', 'language_rule', 'In some common words, the letter l is written but not pronounced. Examples: could, should, would, walk, talk, half, calm, chalk and folk.', 'In words like walk and half, the l is silent.', 'Walk and talk: the l walks quietly.', 'built-in', 'public', true),
  ('f56d6703-9341-56de-8697-42d844cdadbd', 'silent-c-s-n-u', 'Silent c, s, n, u: science, island, autumn, guess', 'silent_letters', 'language_rule', 'Some letters are written but not pronounced. Examples: science and scissors have a silent c; island has a silent s; autumn and column have a silent n; guess, build and guitar have a silent u.', 'Some letters are silent in words like island and autumn.', 'I land on an island: the s is silent.', 'built-in', 'public', true),
  ('258cb0d3-f220-55dd-8116-9a7868bc7bd2', 'es-after-s-sh-ch-x-z-o', 'he/she + -es: watches, fixes, goes', 'verb_endings', 'language_rule', 'After verbs ending in s, sh, ch, x, z or o, add es for he, she or it. Examples: watches, washes, fixes, goes and does.', 'After s, sh, ch, x, z or o, add e s.', 'Sassy sounds need es: watch becomes watches.', 'built-in', 'public', true),
  ('b4efffa7-dd5d-5125-99b2-1cbd0aa5fa67', 's-after-y-verbs', 'consonant + y → ies: studies, flies; vowel + y → ys: plays', 'verb_endings', 'language_rule', 'For he, she or it, change y to ies after a consonant: study becomes studies and fly becomes flies. After a vowel plus y, simply add s: play becomes plays and enjoy becomes enjoys.', 'Consonant plus y becomes i e s; vowel plus y adds s.', 'Consonant y? Change y to ies.', 'built-in', 'public', true),
  ('2952e6c4-acd8-5fea-bdfd-ff4328d387ea', 'ea-vs-ee', 'ea or ee: meat/meet, sea/see, week/weak', 'vowels_and_letter_patterns', 'language_rule', 'The sounds /iː/ can be spelled ea or ee: team, beach, meat, meet, teeth and speech. Some pairs sound the same but have different meanings, such as meat and meet or sea and see.', 'The long e sound can be spelled e a or e e.', 'Eat meat at the beach; see the team this week.', 'built-in', 'public', true),
  ('2c1ae1fe-85e0-5edb-8ba3-56507739c07d', 'ai-ay-oi-oy', 'ai/ay and oi/oy: rain, day, coin, boy', 'vowels_and_letter_patterns', 'language_rule', 'Use ai and oi inside a word: rain, wait, coin and noise. Use ay and oy at the end of a word or syllable: day, stay, boy and enjoy.', 'Use a i and o i inside words; a y and o y at the end.', 'Inside: ai, oi. At the end: ay, oy.', 'built-in', 'public', true),
  ('383d7c48-91b5-5182-a990-a966d71ea784', 'ous-endings', 'Adjectives with -ous: dangerous, famous, nervous', 'prefixes_and_suffixes', 'language_rule', 'Many adjectives end in ous: dangerous, famous, nervous, serious, curious and delicious. Do not write ouse or us at the end.', 'Many adjectives end in o u s.', 'Dangerous, famous, curious: they all finish with ous.', 'built-in', 'public', true),
  ('ebb6e77d-12d0-5db4-9a67-36a3bcfda932', 'logistics-tricky-letters', 'Logistics words: warehouse, receive, schedule', 'business_and_logistics_english', 'language_rule', 'Common logistics words often have difficult letter patterns: warehouse, shipment, receive, invoice, delivery, schedule, equipment, receipt and inventory. Learn them as complete words and check the vowels carefully.', 'Learn logistics words like warehouse, receive and schedule.', 'Receive: e before i, except after c.', 'built-in', 'public', true)
on conflict (slug) do nothing;

